package aterm

import (
	"math"
	"strconv"
	"strings"
)

// The conversions between ATerms and the builtin slots of the terms
// generated by gomgo, after Java Gom's AbstractType (convertATermTo*,
// toATerm, toStringBuilder). A conversion that fails panics with Java
// Gom's RuntimeException message ("Not an Int : …").

// GomError is the panic of a failed conversion of an ATerm into a Gom
// term: Java Gom's RuntimeException ("Not an Int : …"), or, when no
// operator of the sort converts the ATerm, its IllegalArgumentException
// ("… is not a T", IllegalArgument set).
type GomError struct {
	Msg             string
	IllegalArgument bool
}

func (e *GomError) Error() string { return e.Msg }

// ATermConverter is Java's tom.library.utils.ATermConverter: it is
// applied to each ATerm before it is converted into a Gom term.
type ATermConverter interface {
	Convert(at ATerm) ATerm
}

// IdConverter is Java's tom.library.utils.IdConverter.
type IdConverter struct{}

// Convert returns at unchanged.
func (IdConverter) Convert(at ATerm) ATerm { return at }

// GomInt is convertATermToInt (Gom's int is a Go int64).
func GomInt(at ATerm, conv ATermConverter) int64 {
	at = conv.Convert(at)
	if i, ok := at.(*ATermInt); ok {
		return int64(i.GetInt())
	}
	panic(&GomError{Msg: "Not an Int : " + at.String()})
}

// GomLong is convertATermToLong.
func GomLong(at ATerm, conv ATermConverter) int64 {
	at = conv.Convert(at)
	if l, ok := at.(*ATermLong); ok {
		return l.GetLong()
	}
	panic(&GomError{Msg: "Not a Long : " + at.String()})
}

// GomFloat is convertATermToFloat.
func GomFloat(at ATerm, conv ATermConverter) float32 {
	at = conv.Convert(at)
	if r, ok := at.(*ATermReal); ok {
		return float32(r.GetReal())
	}
	panic(&GomError{Msg: "Not a Float : " + at.String()})
}

// GomDouble is convertATermToDouble.
func GomDouble(at ATerm, conv ATermConverter) float64 {
	at = conv.Convert(at)
	if r, ok := at.(*ATermReal); ok {
		return r.GetReal()
	}
	panic(&GomError{Msg: "Not a Double : " + at.String()})
}

// GomBoolean is convertATermToBoolean: an int, 0 for false.
func GomBoolean(at ATerm, conv ATermConverter) bool {
	at = conv.Convert(at)
	if i, ok := at.(*ATermInt); ok {
		return i.GetInt() != 0
	}
	panic(&GomError{Msg: "Not a Boolean : " + at.String()})
}

// GomChar is convertATermToChar: an int, the code of the char minus '0'.
func GomChar(at ATerm, conv ATermConverter) rune {
	at = conv.Convert(at)
	if i, ok := at.(*ATermInt); ok {
		return rune(i.GetInt() + '0')
	}
	panic(&GomError{Msg: "Not a Char : " + at.String()})
}

// GomString is convertATermToString: a quoted constant.
func GomString(at ATerm, conv ATermConverter) string {
	at = conv.Convert(at)
	if a, ok := at.(*ATermAppl); ok && a.GetAFun().IsQuoted() && a.GetArity() == 0 {
		return a.GetName()
	}
	panic(&GomError{Msg: "Not a String : " + at.String()})
}

// GomTerm is the ATerm of a Gom slot of sort ATerm or ATermList.
func GomTerm(at ATerm, conv ATermConverter) ATerm {
	return conv.Convert(at)
}

// MakeGomInt is the ATerm of an int slot.
func MakeGomInt(v int64) ATerm { return GetInstance().MakeInt(int(v)) }

// MakeGomLong is the ATerm of a long slot.
func MakeGomLong(v int64) ATerm { return GetInstance().MakeLong(v) }

// MakeGomReal is the ATerm of a float or double slot.
func MakeGomReal(v float64) ATerm { return GetInstance().MakeReal(v) }

// MakeGomBoolean is the ATerm of a boolean slot (1 or 0).
func MakeGomBoolean(v bool) ATerm {
	if v {
		return GetInstance().MakeInt(1)
	}
	return GetInstance().MakeInt(0)
}

// MakeGomChar is the ATerm of a char slot: its code minus '0'.
func MakeGomChar(v rune) ATerm { return GetInstance().MakeInt(int(v) - '0') }

// MakeGomString is the ATerm of a String slot: a quoted constant.
func MakeGomString(v string) ATerm {
	f := GetInstance()
	return f.MakeAppl(f.MakeAFun(v, 0, true))
}

// JavaDouble formats v as Java's Double.toString does (the text of a
// Gom double slot): the shortest decimal that reads back as v, with a
// ".0" for an integral value, in computerized scientific notation
// ("1.0E10") outside [1e-3, 1e7).
func JavaDouble(v float64) string { return javaFloat(v, 64) }

// JavaFloat formats v as Java's Float.toString does.
func JavaFloat(v float32) string { return javaFloat(float64(v), 32) }

func javaFloat(v float64, bits int) string {
	switch {
	case math.IsNaN(v):
		return "NaN"
	case math.IsInf(v, 1):
		return "Infinity"
	case math.IsInf(v, -1):
		return "-Infinity"
	case v == 0:
		if math.Signbit(v) {
			return "-0.0"
		}
		return "0.0"
	}
	if a := math.Abs(v); a >= 1e-3 && a < 1e7 {
		s := strconv.FormatFloat(v, 'f', -1, bits)
		if !strings.Contains(s, ".") {
			s += ".0"
		}
		return s
	}
	s := strconv.FormatFloat(v, 'E', -1, bits) // 1.2345E+08
	mant, exp, _ := strings.Cut(s, "E")
	if !strings.Contains(mant, ".") {
		mant += ".0"
	}
	exp = strings.TrimPrefix(exp, "+")
	neg := strings.HasPrefix(exp, "-")
	exp = strings.TrimLeft(strings.TrimPrefix(exp, "-"), "0")
	if exp == "" {
		exp = "0"
	}
	if neg {
		exp = "-" + exp
	}
	return mant + "E" + exp
}

// MakeListFromSlice is the list of the given terms (Java's
// ATermAppl.getArguments() returns a list, the Go GetArguments a slice).
func (f *Factory) MakeListFromSlice(args []ATerm) *ATermList {
	l := f.MakeListEmpty()
	for i := len(args) - 1; i >= 0; i-- {
		l = f.MakeList(args[i], l)
	}
	return l
}
